// Line Chart with Missing Data — Basic, route: jsx
// Source: line-chart-missing-data_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from lineMissing ----
type ClosePoint = { date: Date; close: number | null };

const DAYS = 240;

/** Index ranges whose closes are dropped, so the line breaks in three visible places. */
const GAPS: [number, number][] = [
  [38, 57],
  [108, 119],
  [174, 196]
];

/** mulberry32: a fixed seed keeps the series identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);
const isMissing = (index: number) => GAPS.some(([from, to]) => index >= from && index <= to);

/** Synthetic daily close, a drifting random walk shaped like a share price. */
const dailyClose: ClosePoint[] = (() => {
  let price = 132;
  let momentum = 0;
  return Array.from({ length: DAYS }, (_, index) => {
    momentum = momentum * 0.9 + (random() - 0.47) * 1.9;
    price = Math.max(60, price + momentum + Math.sin(index / 31) * 0.8);
    return {
      date: new Date(2024, 0, 2 + index),
      close: isMissing(index) ? null : Math.round(price * 100) / 100
    };
  });
})();

const MARGIN = { top: 16, right: 20, bottom: 36, left: 52 };

/** One point per day in chronological order; a null close is a gap in the record. */
export type Data = { date: Date; close: number | null }[];

export default function LineChartMissingData({
  data = dailyClose,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleTime()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data, (d) => d.close ?? 0) ?? 0])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  // One generator, two datasets: .defined breaks the line, the pre-filtered copy does not.
  const line = useMemo(
    () =>
      d3
        .line<Data[number]>()
        .defined((d) => d.close !== null)
        .x((d) => x(d.date))
        .y((d) => y(d.close ?? 0)),
    [x, y]
  );

  const brokenPath = useMemo(() => line(data) ?? '', [data, line]);
  const interpolatedPath = useMemo(
    () => line(data.filter((d) => d.close !== null)) ?? '',
    [data, line]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(6).map((v) => ({ value: d3.timeFormat('%b %Y')(v), offset: x(v) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: d3.format('$,.0f')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Line chart of a daily close series with gaps where data is missing">
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <path d={interpolatedPath} fill="none" stroke="var(--muted)" strokeWidth={1.5}
              strokeOpacity={0.55} strokeLinejoin="round" strokeLinecap="round" />
        <path d={brokenPath} fill="none" stroke="var(--accent)" strokeWidth={2}
              strokeLinejoin="round" strokeLinecap="round" />
        <g transform={`translate(8,${innerHeight - 32})`} fontSize={11} fill="var(--muted)">
          <line x1={0} x2={18} y1={0} y2={0} stroke="var(--accent)" strokeWidth={2} />
          <text x={24} dy="0.32em">observed</text>
          <line x1={0} x2={18} y1={16} y2={16} stroke="var(--muted)" strokeWidth={1.5}
                strokeOpacity={0.55} />
          <text x={24} y={16} dy="0.32em">interpolated</text>
        </g>
      </g>
    </svg>
  );
}
